// LoadGameServer loads the gameServerMetricsHistory's GameServer into the .R struct
func (o *GameServerMetricsHistory) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServer = nil
	o.R.Loaded.GameServer = false

	related, err := o.GameServer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.GameServerMetricsHistories = GameServerMetricsHistorySlice{o}

	o.R.GameServer = related
	o.R.Loaded.GameServer = true
	return nil
}

// LoadGameServer loads the gameServerMetricsHistory's GameServer into the .R struct
func (os GameServerMetricsHistorySlice) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.GameServer = nil
		o.R.Loaded.GameServer = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	gameServerMetricsHistoryByKey := make(map[string][]*GameServerMetricsHistory, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		gameServerMetricsHistoryByKey[o.GameServerID] = append(gameServerMetricsHistoryByKey[o.GameServerID], o)
	}

	for _, rel := range gameServers {

		owners, ok := gameServerMetricsHistoryByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.GameServer != nil {
				continue
			}

			rel.R.GameServerMetricsHistories = append(rel.R.GameServerMetricsHistories, o)

			o.R.GameServer = rel

		}
	}

	return nil
}

type gameServerMetricsHistoryJoins[Q dialect.Joinable] struct {
	typ        string
	GameServer modAs[Q, gameServerColumns]
}

func (j gameServerMetricsHistoryJoins[Q]) aliasedAs(alias string) gameServerMetricsHistoryJoins[Q] {
	return buildGameServerMetricsHistoryJoins[Q](buildGameServerMetricsHistoryColumns(alias), j.typ)
}

func buildGameServerMetricsHistoryJoins[Q dialect.Joinable](cols gameServerMetricsHistoryColumns, typ string) gameServerMetricsHistoryJoins[Q] {
	return gameServerMetricsHistoryJoins[Q]{
		typ: typ,
		GameServer: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.GameServerID),
					))
				}

				return mods
			},
		},
	}
}
